package wire

import (
	"log/slog"

	"checkdee-backend/internal/config"
	"checkdee-backend/internal/db"
	"checkdee-backend/internal/handler"
	"checkdee-backend/internal/lineclient"
	"checkdee-backend/internal/repository"
	"checkdee-backend/internal/server"
	"checkdee-backend/internal/usecase"
)

func InitializeServer(logger *slog.Logger) (*server.Server, error) {
	cfg, err := config.Load()
	if err != nil {
		return nil, err
	}

	// checkdee_app (least-privilege role, see AppDatabaseURL doc comment),
	// not the owner/superuser DatabaseURL used by migrations/seedowner/tests.
	pool, err := db.Connect(cfg.AppDatabaseURL)
	if err != nil {
		return nil, err
	}

	userRepo := repository.NewUserRepository(pool)
	refreshTokenRepo := repository.NewRefreshTokenRepository(pool)
	lineClient := lineclient.New(cfg.LineChannelID, cfg.LineChannelSecret)
	jwtIssuer := usecase.NewJWTIssuer(cfg.JWTSecret)

	authUsecase := usecase.NewAuthUsecase(userRepo, refreshTokenRepo, lineClient, jwtIssuer)
	authHandler := handler.NewAuthHandler(authUsecase)

	return server.New(cfg, logger, authHandler, jwtIssuer), nil
}
